function MonthSelfAssessment({ language, onSelect }: Props) {
    const questions = language === 'en' ? ['I can name my feelings', 'I can calm myself with the traffic light', 'I treat others kindly', 'I know who to ask for help'] : language === "miq" ? toMiskituDraft(['Sé nombrar mis emociones', 'Me sé calmar con el semáforo', 'Trato bien a los demás', 'Sé a quién pedir ayuda']) : ['Sé nombrar mis emociones', 'Me sé calmar con el semáforo', 'Trato bien a los demás', 'Sé a quién pedir ayuda'];
    const [answers, setAnswers] = useState<Record<number, number>>({});
    function answer(question: number, value: number) { const next = { ...answers, [question]: value }; setAnswers(next); onSelect(Object.keys(next).length === questions.length ? 'complete' : ''); }
    return <View style={styles.assessmentWrap}><Text style={styles.gameTitle}>{language === 'en' ? 'How was this month?' : language === "miq" ? toMiskituDraft('¿Cómo te fue este mes?') : '¿Cómo te fue este mes?'}</Text><View style={styles.assessmentLegend}><Text style={styles.legendText}>{language === 'en' ? 'Still learning' : language === "miq" ? toMiskituDraft('Todavía no') : 'Todavía no'}</Text><Text style={styles.legendText}>{language === 'en' ? 'A little' : language === "miq" ? toMiskituDraft('Un poco') : 'Un poco'}</Text><Text style={styles.legendText}>{language === 'en' ? 'Yes!' : language === "miq" ? toMiskituDraft('¡Sí!') : '¡Sí!'}</Text></View>{questions.map((question, index) => <View key={question} style={styles.assessmentRow}><Text style={styles.assessmentQuestion}>{question}</Text><View style={styles.faceRow}>{[0, 1, 2].map((value) => <Pressable accessibilityRole="radio" accessibilityState={{ selected: answers[index] === value }} key={value} onPress={() => answer(index, value)} style={[styles.faceChoice, answers[index] === value && styles.faceChoiceSelected]}><EmotionDrop emotion={value === 0 ? 'sadness' : value === 1 ? 'joy' : 'love'} size={34} faded={answers[index] !== undefined && answers[index] !== value}/></Pressable>)}</View></View>)}<View style={styles.teacherNote}><PioMark pose="hello" size={38}/><Text style={styles.teacherNoteText}>{language === 'en' ? 'There are no wrong answers. Your teacher uses this to help you.' : language === "miq" ? toMiskituDraft('No hay respuestas malas. Tu profe lo usa para ayudarte mejor.') : 'No hay respuestas malas. Tu profe lo usa para ayudarte mejor.'}</Text></View><Text style={styles.roundText}>{Object.keys(answers).length} {t('of', language)} 4</Text></View>;
}
